// The engine-affecting [Settings] as the C ABI's by-value `FunputConfig`: the one
// mapping both shells share, so a new engine option is added here once. Split from
// ffi/handle.h, which owns the engine handle that `configure` pushes this into.

#ifndef FUNPUT_FFI_CONFIG_H
#define FUNPUT_FFI_CONFIG_H

#include <cstdint>

#include "funput.h" // generated by cbindgen; on the include path via CMake
#include "settings/settings.h"

namespace funput {

// The engine-affecting options of `settings`, as the C ABI's by-value config. The
// runtime VI/EN state is deliberately absent: that is the live toggle
// (`setEnabled`), not a persisted engine option. So are the gõ tắt options,
// which the C ABI keeps as their own functions — see `Handle::setShortcutsEnabled`.
inline FunputConfig engineConfig(const Settings &s) {
    return FunputConfig{
        static_cast<uint8_t>(s.method),
        static_cast<uint8_t>(s.toneStyle),
        s.smartRestore,
        s.eagerRestore,
        s.spellCheck,
        s.autoCapitalize,
    };
}

} // namespace funput

#endif // FUNPUT_FFI_CONFIG_H
